def solve(sizes, days):
    low, high = max(sizes), sum(sizes)
    while low < high:
        capacity = (low + high) // 2
        used, current = 1, 0
        for size in sizes:
            if current + size > capacity:
                used += 1
                current = 0
            current += size
        if used <= days:
            high = capacity
        else:
            low = capacity + 1
    return low

