def solve(n, edges, start, target):
    import heapq
    graph = [[] for _ in range(n)]
    for u, v, cost in edges:
        graph[u].append((v, cost))
    distance = [float('inf')] * n
    distance[start] = 0
    heap = [(0, start)]
    while heap:
        cost, node = heapq.heappop(heap)
        if cost != distance[node]:
            continue
        if node == target:
            return cost
        for nxt, weight in graph[node]:
            candidate = cost + weight
            if candidate < distance[nxt]:
                distance[nxt] = candidate
                heapq.heappush(heap, (candidate, nxt))
    return -1

def solve(packages, target):
    impossible = target + 1
    dp = [impossible] * (target + 1)
    dp[0] = 0
    for amount in range(1, target + 1):
        for size in packages:
            if size <= amount:
                dp[amount] = min(dp[amount], dp[amount - size] + 1)
    return -1 if dp[target] == impossible else dp[target]

