    dp = [0] * cols
    dp[0] = 1
    for row in blocked:
        for c, cell in enumerate(row):
            if cell == 1:
                dp[c] = 0
            elif c > 0:
                dp[c] = (dp[c] + dp[c - 1]) % 1000000007
    return dp[-1]

def solve(capacity, operations):
    from collections import OrderedDict
    cache = OrderedDict()
    result = []
    for operation in operations:
        action, key = operation[:2]
        if action == 'get':
            if key in cache:
                result.append(cache[key])
                cache.move_to_end(key)
            else:
                result.append(-1)
        else:
            cache[key] = operation[2]
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)
    return result

def solve(ttl, operations):
    store = {}
    result = []
    for operation in operations:
        action, time, key = operation[:3]
        if action == 'set':
            store[key] = (operation[3], time + ttl)
        elif key in store and time < store[key][1]:
            result.append(store[key][0])
        else:
            store.pop(key, None)
            result.append(-1)
    return result

