def solve(n, operations):
    parent = list(range(n))
    size = [1] * n
    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node
    result = []
    for action, a, b in operations:
        ra, rb = find(a), find(b)
        if action == 'same':
            result.append(ra == rb)
        elif ra != rb:
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]
    return result
